def main():
    scan=json.loads((OUT/'static-callgraph.json').read_text())['modules']
    rows=[]
    for ident,title,files,functions,entry,dup,decision,score,existing,third,reason in DATA:
        paths=files.split(';')
        callers=[{'file':m['file'],'line':c['line'],'target':c['target']} for m in scan for c in m['calls']
                 if any(c['target'].split('.')[-1]==f.split('.')[-1] for f in functions.split(';'))]
        rows.append(dict(id=ident,title=title,files=paths,functions=functions.split(';'),entry=entry,
            frequency='runtime call counts in runtime-profile.json when measured; otherwise NOT_MEASURED',
            responsibility=dup,public_api='retained; dynamic registrations are inventoried separately',
            deletion_scope='deletion-plan.json' if decision=='SIMPLIFY_EXISTING' else 'not authorized by current evidence',
            state_and_side_effects='input transforms only' if ident=='D01' else 'provider route dispatch; budget ownership unchanged' if ident=='A01' else reason,
            alternatives={'A':'retain current implementation','B':existing,'C':third},
            effort='bounded' if decision=='SIMPLIFY_EXISTING' else 'requires additional compatibility evidence',
            risk=score[3],score_dimensions=score,priority=3*score[0]+4*score[1]+2*score[2]-4*score[3]-3*score[4],
            tests='candidate-equivalence.xml and focused regressions' if decision=='SIMPLIFY_EXISTING' else 'see reason / benchmark-results.json',
            needs_paid_api=False,decision=decision,reason=reason,syntactic_callers=callers))
    rows.sort(key=lambda r:r['priority'],reverse=True)
    (OUT/'replacement-opportunities.json').write_text(json.dumps({'score_rule':'3*removable_code+4*duplicate_responsibility+2*reliability-4*risk-3*dependency_cost; dimensions 0..5, ranking only',
        'scope':'25 reviewed responsibility clusters covering A-H; full syntactic matches in capability-scan.json. This is not proof every dynamic runtime target was resolved.', 'candidates':rows},indent=2))


if __name__=='__main__':main()
